option.value:
body { font-family: Inter, "Segoe UI", Tahoma, "Noto Sans Arabic", system-ui, sans-serif; color: var(--ink); line-height: 1.6; }
h1,h2,h3,strong,.brand-lockup { font-family: inherit; font-weight: 600; }
button { color: inherit; }
.workspace { min-height: 100vh; display: flex; }
.sidebar { position: fixed; inset: 0 auto 0 0; z-index: 20; width: 264px; display: flex; flex-direction: column; padding: 28px 17px 16px; background: var(--surface); border-right: 1px solid var(--line); }
.brand-lockup { display: flex; gap: 11px; align-items: center; padding: 0 9px; color: var(--ink); }
.brand-mark { width: 38px; height: 38px; display: grid; place-items: center; border-radius: 11px; color: var(--surface); background: var(--forest); }
.brand-lockup strong { display: block; font-size: 16px; letter-spacing: -.5px; }
.brand-lockup small { display: block; margin-top: 3px; color: var(--text-muted); font-size: 12px; font-weight: 500; letter-spacing: 0; }
.sidebar-caption { margin: 34px 12px 12px; color: var(--text-muted); font-size: 13px; font-weight: 600; letter-spacing: 0; }
.side-nav { display: grid; gap: 7px; }
.nav-link { min-height: 48px; display: flex; align-items: center; gap: 13px; padding: 0 13px; border-radius: 9px; color: var(--text-muted); font-size: 16px; font-weight: 500; transition: background .16s, color .16s; }
.nav-link:hover { color: var(--ink); background: var(--surface-hover); }
.nav-link.active { color: var(--surface); background: var(--forest); box-shadow: inset 4px 0 var(--accent); font-weight: 600; }
.nav-link.active svg { color: var(--surface); }
.nav-link>svg { flex: 0 0 21px; }
.nav-shortcut { margin-left: auto; font-size: 18px; color: var(--text-muted); }
.nav-status { margin-left: auto; padding: 4px 8px; border-radius: 6px; color: var(--forest); background: var(--surface-soft); font-size: 12px; font-weight: 600; letter-spacing: 0; }
.lower-caption { margin-top: 31px; }
.sidebar-spacer { flex: 1; }
.sidebar-note { display: flex; gap: 9px; padding: 12px 10px; margin-bottom: 13px; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); }
.note-icon { color: var(--forest-muted); padding-top: 1px; }
.sidebar-note strong { font-size: 14px; }
.sidebar-note p { margin: 3px 0 0; color: var(--text-muted); font-size: 13px; line-height: 1.55; }
.sidebar-user { display: flex; align-items: center; gap: 9px; padding: 11px 3px 2px; border-top: 1px solid var(--line); }
.avatar,.topbar-avatar { flex: 0 0 33px; width: 33px; height: 33px; display: grid; place-items: center; border-radius: 50%; color: var(--forest); background: var(--line); font-size: 13px; font-weight: 600; }
.sidebar-user-name { min-width: 0; flex: 1; }
.sidebar-user-name strong,.sidebar-user-name small { display: block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.sidebar-user-name strong { font-size: 14px; }
.sidebar-user-name small { margin-top: 3px; color: var(--text-muted); font-size: 12px; }
.icon-button { width: 38px; height: 38px; display: inline-grid; place-items: center; border: 0; border-radius: 8px; color: var(--forest); background: transparent; }
.icon-button:hover { color: var(--ink); background: var(--line); }
.main-area { width: calc(100% - 264px); min-height: 100vh; margin-left: 264px; }
.topbar { height: 72px; display: flex; align-items: center; justify-content: space-between; padding: 0 43px; border-bottom: 1px solid var(--line); background: var(--surface); }
.breadcrumb { display: flex; align-items: center; gap: 9px; color: var(--text-muted); font-size: 14px; }
.breadcrumb strong { color: var(--forest); font-size: 14px; font-weight: 600; }
.breadcrumb-slash { color: var(--text-muted); }
.topbar-right { display: flex; align-items: center; gap: 19px; }
.model-badge { display: flex; align-items: center; gap: 7px; padding: 7px 10px; border: 1px solid var(--line); border-radius: 20px; color: var(--forest); background: var(--surface); font-size: 13px; }
.model-badge>span:first-child,.online-mark i { width: 7px; height: 7px; display: inline-block; border-radius: 50%; background: var(--success); box-shadow: 0 0 0 3px var(--success-soft); }
.model-badge-short { display: none; }
.topbar-avatar { flex-basis: 31px; width: 31px; height: 31px; }
.page-content { max-width: 1460px; padding: 38px 43px 56px; margin: 0 auto; }
.page-stack { display: flex; flex-direction: column; gap: 24px; animation: page-enter .22s ease-out both; }
.page-intro { display: flex; align-items: end; justify-content: space-between; gap: 24px; padding-bottom: 3px; }
.eyebrow,.micro-label { display: flex; align-items: center; gap: 7px; color: var(--forest); font-size: 13px; font-weight: 600; letter-spacing: 0; }
.eyebrow-dot { width: 6px; height: 6px; display: inline-block; border-radius: 50%; background: var(--forest-muted); }
.page-intro h1,.welcome-row h1 { margin: 11px 0 6px; font-size: clamp(30px, 2.7vw, 38px); line-height: 1.2; letter-spacing: -.5px; font-weight: 700; }
.page-intro p,.welcome-row p { max-width: 650px; margin: 0; color: var(--text-muted); font-size: 16px; line-height: 1.65; }
.button { min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 9px; padding: 0 16px; border: 1px solid transparent; border-radius: 8px; font-size: 15px; font-weight: 600; transition: transform .15s, background .15s, border-color .15s; }
.button:hover:not(:disabled) { transform: translateY(-1px); }
.button:active:not(:disabled) { transform: translateY(0); }
.button:disabled { cursor: not-allowed; opacity: .72; }
.button-dark { color: white; background: var(--forest); box-shadow: 0 4px 10px #183b3217; }
.button-dark:hover:not(:disabled) { background: var(--forest-hover); }
.button-outline { color: var(--forest); border-color: var(--line); background: var(--surface); }
.button-outline:hover:not(:disabled) { border-color: var(--forest); background: var(--surface-soft); }
.button-light { color: var(--forest); background: var(--surface); }
.button-light:hover:not(:disabled) { background: var(--surface-soft); }
.button-small { min-height: 40px; padding: 0 12px; font-size: 14px; }
.button-wide { width: 100%; margin-top: 4px; }
.button-danger { color: var(--danger); border-color: var(--line); background: var(--surface); }
.stat-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 13px; }
.stat-card { min-height: 132px; padding: 20px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); box-shadow: 0 2px 8px #183b3208; }
.stat-top { display: flex; align-items: center; justify-content: space-between; }
.stat-label { color: var(--text-muted); font-size: 13px; font-weight: 600; letter-spacing: 0; }
.stat-icon { width: 36px; height: 36px; display: grid; place-items: center; border-radius: 9px; color: var(--forest); background: var(--surface-soft); }
.stat-card>strong { display: block; margin-top: 13px; font-size: 22px; line-height: 1.25; letter-spacing: -.8px; }
.stat-hint { display: block; margin-top: 4px; color: var(--text-muted); font-size: 13px; }
.stat-card>strong .stat-coming-soon { color: var(--forest); font-size: 16px; font-weight: 600; letter-spacing: 0; }
.model-stat>strong { font-size: 18px; margin-top: 15px; }
.online-mark { display: flex; align-items: center; gap: 6px; color: var(--forest); font-size: 12px; font-weight: 600; letter-spacing: .1px; }
.dashboard-grid { display: grid; grid-template-columns: minmax(0,1.35fr) minmax(300px,.9fr); gap: 14px; }
.panel { border: 1px solid var(--line); border-radius: 12px; background: var(--surface); box-shadow: 0 2px 8px #183b3208; transition: border-color .18s ease, box-shadow .18s ease; }
.chart-panel,.recent-panel,.conversations-panel { min-height: 310px; padding: 20px; }
.panel-heading { display: flex; align-items: center; justify-content: space-between; gap: 15px; }
.panel-heading h2 { margin: 0; font-size: 20px; letter-spacing: -.3px; }
.quiet-link,.icon-link { display: inline-flex; align-items: center; gap: 7px; color: var(--forest); font-size: 14px; font-weight: 600; }
.quiet-link:hover,.icon-link:hover { color: var(--forest); }
.icon-link { width: 29px; height: 29px; justify-content: center; border: 1px solid var(--line); border-radius: 7px; }
.chart-caption { display: flex; align-items: center; gap: 7px; margin-top: 23px; color: var(--text-muted); font-size: 13px; }
.chart-key { width: 15px; height: 2px; border-radius: 2px; background: var(--forest-muted); }
.chart-wrap { width: 100%; height: 183px; margin-top: 3px; }
.chart-disclaimer { margin: 4px 0 0; color: var(--text-muted); font-size: 12px; line-height: 1.5; }
.empty-state { min-height: 200px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.empty-icon { width: 39px; height: 39px; display: grid; place-items: center; margin-bottom: 11px; border-radius: 12px; color: var(--forest-muted); background: var(--line); }
.empty-state>strong { font-size: 14px; }
.empty-state>p { max-width: 260px; margin: 5px 0 13px; color: var(--text-muted); font-size: 12px; line-height: 1.6; }
.recent-list { margin-top: 18px; }
.recent-item { display: flex; align-items: center; gap: 9px; padding: 10px 8px; border-bottom: 1px solid var(--line); border-radius: 7px; transition: background .16s ease; }
.recent-item:hover { background: var(--surface-soft); }
.recent-item:last-child { border-bottom: 0; }
.recent-car { width: 31px; height: 31px; display: grid; place-items: center; border-radius: 8px; color: var(--forest-muted); background: var(--line); }
.recent-item-copy { min-width: 0; flex: 1; }
.recent-item-copy strong,.recent-item-copy small,.recent-price small { display: block; }
.recent-item-copy strong { overflow: hidden; color: var(--forest); font-size: 12px; white-space: nowrap; text-overflow: ellipsis; }
.recent-item-copy small { margin-top: 4px; color: var(--text-muted); font-size: 12px; }
.recent-price { text-align: right; font-size: 12px; font-weight: 600; }
.recent-price small { margin-top: 3px; color: var(--text-muted); font-size: 12px; font-weight: 400; }
.add-prediction-row { display: flex; align-items: center; justify-content: space-between; padding-top: 12px; margin-top: 5px; border-top: 1px solid var(--line); color: var(--forest-muted); font-size: 12px; font-weight: 600; }
.add-prediction-row span { display: flex; align-items: center; gap: 7px; }
.dashboard-bottom { display: grid; grid-template-columns: minmax(0,1.35fr) minmax(260px,.9fr); gap: 14px; }
.dashboard-estimate { position: relative; padding: clamp(28px,4vw,48px); overflow: hidden; border: 1px solid var(--line); border-top: 4px solid var(--accent); border-radius: 14px; background: var(--surface); box-shadow: 0 8px 24px #183b3210; }
.dashboard-estimate-content { position: relative; z-index: 1; }
.dashboard-estimate-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 15px; }
.dashboard-estimate-heading h2 { margin: 0; color: var(--ink); font-size: clamp(23px,2vw,28px); letter-spacing: -.4px; }
.estimate-date { color: var(--forest); font-size: 14px; }
.dashboard-estimate-skeleton { height: 150px; margin-top: 20px; }
.dashboard-estimate-empty { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding-top: 24px; }
.dashboard-estimate-empty p { color: var(--forest); font-size: 16px; }
.dashboard-estimate-unit { margin: 10px 0 17px; color: var(--text-muted); font-size: 15px; }
.dashboard-estimate-content>.quiet-link { min-height: 40px; }
.dashboard-estimate .price-reference { max-width: 840px; margin: 19px auto 0; }
.dashboard-estimate-unit { text-align: center; }
.dashboard-estimate-content>.quiet-link { display: flex; width: max-content; margin: 0 auto; }
.dashboard-estimate .price-reference-value { color: var(--forest); font-size: clamp(48px,6vw,68px); font-weight: 700; }
.dashboard-estimate .price-range-track { height: 12px; }
.dashboard-estimate .price-range-marker { width: 22px; height: 22px; }
.dashboard-estimate .price-range-endpoint strong { font-size: 16px; }
.dashboard-estimate .price-range-caption { font-size: 14px; }
.conversations-panel { min-height: 195px; }
.coming-soon-panel { display: flex; flex-direction: column; align-items: flex-start; justify-content: center; }
.coming-soon-panel>p { max-width: 510px; margin: 16px 0 0; color: var(--forest); font-size: 15px; line-height: 1.65; }
.conversation-list { margin-top: 13px; }
.conversation-row { display: flex; align-items: center; gap: 10px; padding: 9px 0; border-bottom: 1px solid var(--line); color: var(--text-muted); }
.conversation-row:last-child { border: 0; }
.conversation-row>span:nth-child(2) { flex: 1; }
.conversation-row strong,.conversation-row small { display: block; }
.conversation-row strong { color: var(--forest); font-size: 12px; }
.conversation-row small { margin-top: 3px; color: var(--text-muted); font-size: 12px; }
.conversation-icon { width: 29px; height: 29px; display: grid; place-items: center; border-radius: 8px; color: var(--forest-muted); background: var(--line); }
.small-muted { margin-top: 25px; color: var(--forest); font-size: 14px; line-height: 1.6; }
.scope-card { padding: 20px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface-soft); }
.scope-icon { width: 36px; height: 36px; display: grid; place-items: center; margin-bottom: 15px; border-radius: 9px; color: var(--surface); background: var(--forest); }
.scope-card h3 { margin: 8px 0 6px; font-size: 16px; }
.scope-card p { margin: 0; color: var(--text-muted); font-size: 14px; line-height: 1.6; }
.scope-card a { display: inline-flex; align-items: center; gap: 6px; margin-top: 15px; color: var(--forest); font-size: 12px; font-weight: 600; }
.welcome-row { display: flex; justify-content: space-between; align-items: end; gap: 20px; }
.welcome-row h1 { margin-top: 11px; }
.page-intro .button { margin-bottom: 3px; }
.form-label,.field-label { display: flex; flex-direction: column; gap: 8px; color: var(--ink); font-size: 15px; font-weight: 600; }
.field-label > span { font-size: 13px; line-height: 1.4; font-weight: 600; letter-spacing: .01em; }
.field-label input,.field-label select,.search-field input,.chat-composer textarea { width: 100%; min-height: 48px; padding: 0 13px; border: 1px solid var(--line); border-radius: 8px; outline: none; color: var(--ink); background: var(--surface); font-family: inherit; font-size: 16px; transition: border .15s, box-shadow .15s; }
.field-label input,.field-label select { font-size: 15px; font-weight: 500; }
.field-label input:focus,.field-label select:focus,.sort-control select:focus,.chat-composer textarea:focus { border-color: var(--forest); box-shadow: 0 0 0 3px var(--accent-soft); }
.field-label input::placeholder { color: var(--text-muted); opacity: .8; }
.field-label input[readonly] { color: var(--text-muted); background: var(--surface); }
.field-error { color: var(--danger); font-size: 12px; font-weight: 600; }
.field-hint { color: var(--text-muted); font-size: 12px; font-weight: 400; line-height: 1.5; }
.required-star { margin-left: 3px; color: var(--accent); font-style: normal; }
.select-wrap { position: relative; display: block; }
.select-wrap select { appearance: none; padding-right: 38px; cursor: pointer; }
.select-wrap select option { padding: 8px; font-family: inherit; font-size: 15px; }
.select-wrap>svg { position: absolute; top: 50%; right: 10px; pointer-events: none; color: var(--text-muted); transform: translateY(-50%); }
.prediction-layout { display: flex; flex-direction: column; gap: 18px; align-items: stretch; }
.prediction-form-panel { padding: clamp(24px,3vw,36px); }
.form-panel-title { display: flex; align-items: center; gap: 10px; padding-bottom: 18px; border-bottom: 1px solid var(--line); }
.form-panel-icon { width: 35px; height: 35px; display: grid; place-items: center; border-radius: 9px; color: var(--forest-muted); background: var(--line); }
.form-panel-title strong,.form-panel-title small { display: block; }
.form-panel-title strong { font-size: 16px; }
.form-panel-title small { margin-top: 4px; color: var(--forest); font-size: 14px; }
.prediction-form { padding-top: 20px; }
.field-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 18px 14px; }
.form-footer { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding-top: 18px; margin-top: 21px; border-top: 1px solid var(--line); }
.form-footer>span { display: flex; align-items: center; gap: 6px; color: var(--text-muted); font-size: 13px; }
.form-footer>span svg { color: var(--forest-muted); }
.result-panel { min-height: 0; padding: clamp(28px,4vw,48px); border: 1px solid var(--line); border-radius: 14px; background: var(--surface); box-shadow: 0 8px 24px #183b320c; }
.result-placeholder,.result-content { display: flex; flex-direction: column; align-items: flex-start; }
.result-orb { width: 43px; height: 43px; display: grid; place-items: center; margin-bottom: 20px; border: 1px solid var(--line); border-radius: 13px; color: var(--surface); background: var(--forest); }
.result-panel .micro-label { color: var(--forest-muted); }
.result-panel h2 { margin: 7px 0 8px; font-size: 18px; letter-spacing: -.5px; }
.result-placeholder>p { margin: 0; color: var(--forest-muted); font-size: 12px; line-height: 1.65; }
.result-divider { width: 100%; height: 1px; margin: 20px 0 13px; background: var(--line); }
.result-fact { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 7px 0; }
.result-fact span { color: var(--text-muted); font-size: 12px; font-weight: 600; letter-spacing: .1px; }
.result-fact strong { color: var(--forest); font-size: 12px; }
.result-ready { background: var(--line); }
.price-reference { width: 100%; }
.price-reference-value { display: block; color: var(--forest); font-size: clamp(40px,5vw,54px); font-weight: 700; line-height: 1.15; letter-spacing: -.5px; text-align: center; overflow-wrap: anywhere; }
.price-range { width: 100%; margin-top: 15px; }
.price-range-track { position: relative; height: 10px; overflow: visible; border-radius: 99px; background: var(--surface-hover); }
.price-range-fill { position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(90deg, var(--accent-muted), var(--accent) 50%, var(--accent-muted)); }
.price-range-marker { position: absolute; top: 50%; left: 50%; width: 18px; height: 18px; border: 3px solid var(--surface); border-radius: 50%; background: var(--forest); box-shadow: 0 0 0 2px var(--forest); transform: translate(-50%,-50%); }
.price-range-labels { display: flex; justify-content: space-between; gap: 12px; margin-top: 12px; }
.price-range-endpoint { display: flex; flex-direction: column; align-items: flex-start; gap: 3px; color: var(--text-muted); font-size: 13px; }
.price-range-endpoint small { color: var(--text-muted); font-size: 13px; font-weight: 500; letter-spacing: 0; }
.price-range-endpoint strong { color: var(--ink); font-size: 16px; font-weight: 600; overflow-wrap: anywhere; }
.price-range-upper { align-items: flex-end; text-align: right; }
.price-range-caption { margin: 12px 0 0; color: var(--text-muted); font-size: 13px; line-height: 1.6; }
.result-content>.price-reference { max-width: 850px; margin: 12px auto 0; }
.result-content>.unit-warning { width: 100%; text-align: center; }
.unit-warning { margin: 5px 0 0; color: var(--text-muted); font-size: 12px; line-height: 1.5; }
.saved-badge { display: flex; align-items: center; gap: 6px; padding: 8px 10px; border-radius: 7px; color: var(--success); background: var(--success-soft); font-size: 13px; font-weight: 600; animation: success-enter .2s ease-out both; }
.result-timestamp { margin: 11px 0; color: var(--text-muted); font-size: 12px; }
.result-disclaimer { display: flex; gap: 7px; padding-top: 13px; margin-top: 18px; border-top: 1px solid var(--line); color: var(--forest-muted); font-size: 12px; line-height: 1.55; }
.result-disclaimer svg { flex: 0 0 auto; }
.training-domain-note { display: flex; align-items: center; gap: 7px; color: var(--text-muted); font-size: 12px; }
.training-domain-note svg { flex: 0 0 auto; color: var(--forest-muted); }
.history-toolbar { display: flex; align-items: center; justify-content: space-between; color: var(--text-muted); font-size: 12px; }
.sort-control { position: relative; display: flex; align-items: center; gap: 8px; }
.sort-control select { min-height: 44px; padding: 0 32px 0 12px; appearance: none; border: 1px solid var(--line); border-radius: 8px; color: var(--ink); background: var(--surface); font: inherit; font-size: 15px; cursor: pointer; }
.sort-control select:hover { border-color: var(--forest); }
.sort-control svg { position: absolute; right: 9px; pointer-events: none; color: var(--forest); }
.history-table-wrap { overflow: hidden; }
.history-table { width: 100%; border-collapse: collapse; text-align: left; }
.history-table th { padding: 13px 15px; color: var(--ink); background: var(--surface-soft); font-size: 13px; letter-spacing: 0; }
.history-table td { padding: 15px; border-top: 1px solid var(--line); color: var(--text-muted); font-size: 13px; }
.history-table tbody tr:hover { background: var(--surface-soft); }
.table-actions { display: flex; align-items: center; gap: 2px; }
.table-car { display: flex; align-items: center; gap: 7px; color: var(--forest); font-size: 12px; font-weight: 600; white-space: nowrap; }
.table-car svg { color: var(--forest-muted); }
.table-secondary { display: block; margin-top: 4px; color: var(--text-muted); font-size: 12px; }
.table-price { color: var(--forest); font-size: 13px; }
.detail-chips { display: flex; flex-wrap: wrap; gap: 4px; max-width: 225px; }
.detail-chips span,.detail-tag { padding: 4px 6px; border-radius: 4px; color: var(--forest-muted); background: var(--line); font-size: 12px; }
.danger-hover:hover { color: var(--danger); background: var(--danger-soft); }
.pagination { display: flex; align-items: center; justify-content: center; gap: 14px; padding: 13px; border-top: 1px solid var(--line); color: var(--text-muted); font-size: 12px; }
.history-table+.pagination { }
.compare-selectors { display: grid; grid-template-columns: 1fr 1fr; gap: 13px; }
.compare-select { padding: 15px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface); }
.compare-panel { padding: 23px; }
.compare-head h2 { margin: 6px 0 20px; font-size: 20px; }
.pipeline-count { display: flex; align-items: center; gap: 7px; color: var(--forest-muted); font-size: 12px; font-weight: 600; letter-spacing: .1px; }
.compare-values { display: grid; grid-template-columns: 1fr 60px 1fr; align-items: stretch; }
.compare-value-card { min-height: 190px; padding: 17px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface); }
.compare-value-card>strong { display: block; margin-top: 9px; color: var(--forest); font-size: clamp(22px,2.4vw,28px); letter-spacing: -.4px; overflow-wrap: anywhere; }
.compare-date { display: block; margin-top: 5px; color: var(--text-muted); font-size: 12px; }
.compare-summary { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 17px; }
.compare-summary span { padding: 4px 6px; border-radius: 4px; color: var(--text-muted); background: var(--line); font-size: 12px; }
.compare-divider { display: grid; place-items: center; }
.compare-divider span { width: 30px; height: 30px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%; color: var(--forest); background: var(--surface); font-size: 12px; font-weight: 600; }
.compare-bars { display: grid; gap: 10px; padding: 14px; margin-top: 13px; border-radius: 8px; background: var(--surface); }
.compare-bar-row { display: grid; grid-template-columns: 72px minmax(50px,1fr) 110px; align-items: center; gap: 10px; color: var(--text-muted); font-size: 12px; }
.compare-bar-row>div { height: 7px; overflow: hidden; border-radius: 5px; background: var(--line); }
.compare-bar-row i { height: 100%; display: block; border-radius: inherit; background: var(--forest-muted); }
.compare-bar-row strong { color: var(--forest); font-size: 12px; text-align: right; }
.difference-row { display: flex; align-items: center; justify-content: space-between; padding: 13px 0; margin-top: 15px; border-top: 1px solid var(--line); color: var(--text-muted); font-size: 12px; }
.difference-row strong { display: flex; align-items: center; gap: 4px; font-size: 16px; }
.difference-row small { display: flex; }
.positive { color: var(--success); }.negative { color: var(--danger); }
.compare-inputs { padding-top: 15px; border-top: 1px solid var(--line); }
.compare-inputs h3 { margin: 0 0 8px; font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.input-diff { display: grid; grid-template-columns: 1fr 1.2fr 20px 1.2fr; align-items: center; gap: 8px; padding: 8px 0; border-bottom: 1px solid var(--line); color: var(--text-muted); font-size: 12px; line-height: 1.5; }
.input-diff>span:first-child { color: var(--text-muted); }
.input-diff>span:not(:first-child) { overflow-wrap: anywhere; }
.compare-panel .chart-disclaimer { margin-top: 12px; font-size: 12px; }
.model-photo-credit { position: absolute; z-index: 3; right: 18px; bottom: 15px; padding: 6px 9px; border-radius: 6px; color: var(--surface); background: rgba(var(--forest-rgb),.76); font-size: 12px; }
.model-photo-credit:hover { text-decoration: underline; text-underline-offset: 3px; }
/* lighter form typography */
.field-label > span > i,
.field-label .required-star { font-weight: 700; }

.field-label input,
.field-label select,
.field-label textarea,
.compare-select select,
.sort-control select {
  font-weight: 500;
}

.prediction-form .field-grid .field-label {
  gap: 7px;
}

.prediction-form .field-grid .field-label span {
  font-size: 13px;
}
